#include <stdio.h>
#include <string.h>
int main(void) {
    char buf[64];
    int found = 0;
    while (scanf("%63s", buf) == 1) {
        if (strcmp(buf, "a") == 0) found = 1;
    }
    printf("%s\n", found ? "YES" : "NO");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    char buf[64];
    if (scanf("%63s", buf) != 1) return 1;
    int v = atoi(buf);
    printf("%d\n", 2 * v);
    return 0;
}

#include <stdio.h>
int main(void) {
    char buf[128];
    int c = 0;
    while (scanf("%127s", buf) == 1) c++;
    printf("%d\n", c);
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void) {
    char tok[128];
    if (scanf("%127s", tok) != 1) return 1;
    if (strstr(tok, "--count=") == tok) {
        printf("FOUND\n");
    } else {
        printf("NOTFOUND\n");
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    char buf[64];
    if (scanf("%63s", buf) != 1) return 1;
    long v = strtol(buf, NULL, 0);
    printf("%ld\n", v);
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void) {
    char tok[128];
    if (scanf("%127s", tok) != 1) return 1;
    if (tok[0] == '-' && tok[1] != '-' && tok[1] != 0) {
        for (int i = 1; tok[i]; i++) {
            printf("-%c\n", tok[i]);
        }
    }
    return 0;
}
